<script setup>import{inject}from'vue';const s=inject('planAdmin');const date=v=>v?new Intl.DateTimeFormat(undefined,{dateStyle:'medium'}).format(new Date(v)):'Not recorded';</script><template><section class="admin-card"><div class="card-heading"><h2>Plan information</h2><RouterLink class="btn-secondary" :to="{name:'admin.plans.edit',params:{id:s.plan.value.id}}">Edit</RouterLink></div><dl class="detail-list"><div><dt>Name</dt><dd>{{s.plan.value.name}}</dd></div><div><dt>Slug</dt><dd>{{s.plan.value.slug}}</dd></div><div><dt>Description</dt><dd>{{s.plan.value.description||'Not provided'}}</dd></div><div><dt>Status</dt><dd class="capitalize">{{s.plan.value.status}}</dd></div><div><dt>Price</dt><dd>{{s.plan.value.currency}} {{s.plan.value.price}}</dd></div><div><dt>Billing period</dt><dd class="capitalize">{{s.plan.value.billing_period}}</dd></div><div><dt>Trial days</dt><dd>{{s.plan.value.trial_days}}</dd></div><div><dt>Created</dt><dd>{{date(s.plan.value.created_at)}}</dd></div><div><dt>Updated</dt><dd>{{date(s.plan.value.updated_at)}}</dd></div></dl></section></template>
